options.styles:
.hn-bg { background:#1e293b; padding:12px 28px; margin:-8px; }
.hn-wrap { display:flex; gap:20px; justify-content:center; align-items:stretch; }
.hn-card { background:#0f172a; border:2px solid #334155; border-radius:10px; padding:20px 28px 16px; text-align:center; flex:1; max-width:440px; display:flex; flex-direction:column; justify-content:center; align-items:center; }
.hn-card.active { border-color:#FF8833; }
a.hn-card { text-decoration:none; transition:transform 0.2s ease, border-color 0.2s ease; cursor:pointer; }
a.hn-card:hover { transform:scale(1.02); border-color:#60a5fa; }
.hn-flow { display:flex; align-items:flex-start; justify-content:center; gap:12px; }
.hn-node { color:white; text-align:center; font-size:13px; line-height:1.3; }
.hn-icon { height:56px; display:flex; align-items:center; justify-content:center; margin-bottom:8px; }
.hn-arrow { color:#64748b; font-size:28px; height:56px; display:flex; align-items:center; }
.hn-here { color:#FF8833; font-weight:700; margin-top:16px; font-size:14px; }
.hn-link { color:#60a5fa; text-decoration:underline; margin-top:16px; font-size:14px; line-height:1.4; }
